      "✦ CLASS ADVANCEMENT — you are now a {class}! New skills unlocked.": "✦ เลื่อนขั้นอาชีพ — บัดนี้คุณคือ {class}! ปลดล็อกสกิลใหม่แล้ว",
      "Level up! Lv {level} — +{points} stat points.": "เลเวลเพิ่มขึ้น! เลเวล {level} — ได้รับแต้มสเตตัส +{points} แต้ม",
      "Job level up! Job Lv {level}/{cap} — +{points} skill point.": "จ็อบเลเวลเพิ่มขึ้น! จ็อบเลเวล {level}/{cap} — ได้รับแต้มสกิล +{points} แต้ม",
