      "☠ The Flame Dragon falls — and behind its throne, the sky TEARS OPEN. The Astral Rift awaits.": "☠ มังกรเพลิงล่มสลาย — ท้องฟ้าเบื้องหลังบัลลังก์ได้ฉีกขาดออก Astral Rift กำลังรอคุณอยู่",
      "✦☠ The Nullking is unmade!": "✦☠ นัลคิงอันตรธานสิ้นสูญ!",
      "🏰 Guardian slain — the guild now posts bounties for {map}!": "🏰 ผู้พิทักษ์ถูกปราบแล้ว — กิลด์เปิดเควสต์ล่าค่าหัวสำหรับ {map}!",
