      " — dropped {gold}z on the way": " — เงินร่วงหล่นระหว่างทาง {gold}z",
      " Hunt and route stopped.": " ระบบล่าออโต้และนำทางหยุดทำงาน",
      "Chapter locked — reach Base Lv {level} for {quest}.": "เนื้อเรื่องถูกล็อก — เลเวลของตัวละครต้องถึง {level} สำหรับเควสต์ {quest}",
