      "Victory! The world is yours to roam. Toggle auto-farm with F.": "มีชัยเหนือทุกสิ่ง! บัดนี้โลกใบนี้เป็นของคุณแล้ว เปิดล่าออโต้ได้ด้วยปุ่ม F",
