      // Class Flavors
      "The salaryman who read every tank guide and finally gets to main one.": "พนักงานออฟฟิศที่อ่านไกด์สายแทงก์มาทุกเล่ม และในที่สุดก็ได้เล่นเป็นตัวหลักเสียที",
      "Front-line bruiser: soaks hits with high VIT, cleaves groups, and shrugs off boss slams. Forgiving for new players.": "นักรบแถวหน้า: รับการโจมตีด้วย VIT ที่สูง, โจมตีกวาดเป็นกลุ่ม, และไม่สะทกสะท้านต่อการทุบของบอส เล่นง่ายสำหรับผู้เล่นใหม่",
      "A courier who turned back-alley reflexes into a whirlwind of blades.": "คนส่งของที่เปลี่ยนปฏิกิริยาตอบสนองในซอยเปลี่ยวให้กลายเป็นพายุหมุนแห่งใบดาบ",
      "Glass scythe: AGI-fueled attack & move speed, huge crits, thin armor. Dance out of the red circles or die in them.": "เคียวกระดาษ: ความเร็วในการโจมตีและเคลื่อนที่ขับเคลื่อนด้วย AGI, คริติคอลรุนแรง, เกราะบาง หลบออกจากวงกลมแดงให้พ้น ไม่อย่างนั้นก็จมกองเลือดอยู่ในนั้น",
      "Rewrites reality like it's buggy software — semicolons optional, fireballs mandatory.": "เขียนความเป็นจริงขึ้นมาใหม่ราวกับว่ามันเป็นซอฟต์แวร์ที่มีบั๊ก — เซมิโคลอนไม่จำเป็น แต่ลูกไฟต้องมา!",
      "Artillery: INT extends spell range and magic damage — burn packs down before they reach you. Weak up close, thirsty for mana.": "ปืนใหญ่เวทมนตร์: INT จะช่วยเพิ่มระยะร่ายและดาเมจเวท — เผาศัตรูให้ราบก่อนที่พวกมันจะเข้าถึงตัว อ่อนแอในระยะประชิด และเปลืองมานามาก",
      "A hobby archer from Earth who never missed a target — and now the targets shoot back.": "นักยิงธนูสมัครเล่นจากโลกมนุษย์ที่ไม่เคยยิงพลาดเป้า — แต่ตอนนี้เป้าหมายกำลังยิงสวนกลับมาแล้ว",
      "Sustained sniper: DEX for unerring hits, AGI to kite. Steady single-target damage from far outside a monster's reach.": "พลซุ่มยิงต่อเนื่อง: เน้น DEX เพื่อการโจมตีที่ไม่พลาดเป้า, ใช้ AGI ในการกะระยะและหลบหลีก ทำดาเมจเป้าหมายเดี่ยวได้อย่างมั่นคงจากระยะที่มอนสเตอร์เอื้อมไม่ถึง",
      "A paramedic who died saving strangers — reborn wielding a blade of dawn and the power to mend.": "เจ้าหน้าที่กู้ชีพที่เสียชีวิตจากการช่วยชีวิตคนแปลกหน้า — เกิดใหม่พร้อมดาบแห่งรุ่งอรุณและพลังแห่งการรักษา",
      "Self-sufficient crusader: melee smites plus a real heal — slower kills, but nearly unkillable when played patiently.": "ครูเซเดอร์ผู้พึ่งพาตนเองได้: โจมตีประชิดด้วยการพิพากษา พร้อมทั้งมีสกิลฮีลจริง — กำจัดศัตรูช้าหน่อย แต่ถ้าเล่นอย่างใจเย็นก็จะแทบไม่มีวันตาย",
      "A gym rat who read every fighting-game frame chart, now in a world that finally lets him throw hands.": "หนุ่มฟิตเนสที่อ่านตารางเฟรมเกมต่อสู้มาทุกเกม ตอนนี้อยู่ในโลกที่เขาจะได้ออกหมัดปล่อยพลังจริงๆ เสียที",
      "Momentum incarnate: fast cheap strikes build Momentum, stun-setups feed detonating palms, and finishers cash it all in. High skill ceiling.": "ศูนย์รวมโมเมนตัม: โจมตีเร็วและใช้ทรัพยากรน้อยเพื่อสะสมโมเมนตัม, ใช้ท่าสตันเพื่อต่อคอมโบฝ่ามือระเบิด, และใช้ท่าปิดฉากเพื่อปลดปล่อยพลังทั้งหมด เพดานทักษะการเล่นสูง",
      "A storm-chaser who drove into the tornado — and woke somewhere the storms answer back.": "นักล่าพายุที่ขับรถเข้าใส่ทอร์นาโด — แล้วตื่นขึ้นมาในสถานที่ที่พายุพร้อมจะตอบรับเสียงเรียกของเขา",
      "Weaver of storms: stack burn, slow, and shock, then detonate them with thunder and fire. Fragile artillery that rewards setup.": "ผู้ถักทอพายุ: ซ้อนทับสถานะเผาไหม้, เชื่องช้า, และช็อต, จากนั้นระเบิดพวกมันด้วยอัสนีและอัคคี ปืนใหญ่เวทมนตร์ที่เปราะบางแต่ให้ผลตอบแทนคุ้มค่าหากวางแผนไว้ดี",

