      "An ethereal nocturnal flower that unfurls its luminescent petals only beneath starry night skies.": "ดอกไม้ยามค่ำคืนอันลึกลับที่คลี่กลีบเรืองแสงเฉพาะใต้ท้องฟ้าพร่างดาว",

