      "A coalesced tempest, raining down sparks and fury.": "พายุที่รวมตัวกัน สาดประกายไฟและความเดือดดาลลงมา",
      "The Zenith Warden": "ผู้พิทักษ์ยอดเขาเซนิท",
      "An ancient construct appointed to guard the highest peaks from intruders.": "โครงสร้างเวทมนตร์โบราณที่ถูกสร้างขึ้นเพื่อพิทักษ์ยอดเขาที่สูงที่สุดจากผู้บุกรุก",
      "Void Wisp": "ดวงไฟว่างเปล่า",
      "A mote of unmade reality, drifting where the stars leak through.": "ละอองแห่งความว่างเปล่า ล่องลอยอยู่ในจุดที่ท้องฟ้ารั่วไหล",
      "Star Reaver": "ผู้ทำลายดวงดาว",
      "A warrior long dead, still swinging a blade of cold starlight.": "อดีตนักรบผู้ล่วงลับ ยังคงแกว่งดาบแสงดาวอันเยือกเย็นอย่างไร้จุดหมาย",
      "Astral Knight": "อัศวินดวงดารา",
      "A sentinel of the rift, armored in condensed moonlight.": "ทหารยามแห่งรอยแยกมิติ สวมชุดเกราะที่ควบแน่นจากแสงจันทร์ยามค่ำ",
      "Rift Manta": "กระเบนรอยแยก",
      "A silent sky-ray that swims between broken constellations and hunts by starlight.": "กระเบนเวหาไร้เสียงที่ว่ายผ่านกลุ่มดาวแตกร้าวและล่าด้วยแสงดารา",
      "Constellation Mite": "ไรกลุ่มดาว",
      "A tiny star-eater that skitters across broken paths between worlds.": "นักกินดาวตัวจ้อยที่วิ่งข้ามเส้นทางแตกร้าวระหว่างโลก",
      "The Nullking": "ราชันความดับสูญ",
      "The crowned end of all things. It does not roar — it simply unmakes.": "จุดจบของสรรพสิ่งผู้สวมมงกุฎ มันไม่ส่งเสียงคำราม — มันเพียงแต่ลบเลือน",
      "Voidmaw Sovereign": "จอมราชันย์แห่งมิติว่างเปล่า",
      "A world-eating tide given a crown. Even the Nullking's throne room keeps its distance.": "กระแสน้ำผู้กลืนกินโลกที่ได้รับมงกุฎ แม้แต่ห้องบัลลังก์ของนัลคิงยังต้องถอยห่าง",
      "Caldera Colossus": "ยักษ์ศิลาลาวาแมกมา",
      "A magma titan sculpted by subterranean pressure and volcanic rage.": "ไททันแมกมาที่ก่อตัวขึ้นจากแรงดันใต้พิภพและความเดือดดาลของภูเขาไฟ",
      "Ancient Behemoth": "เบเฮมอธดึกดำบรรพ์",
      "A primordial elder beast whose heavy strides shake the roots of the ancient woods.": "สัตว์ร้ายโบราณดึกดำบรรพ์ที่มีฝีย่างก้าวหนักหน่วงจนสั่นสะเทือนรากไม้แห่งพงไพร",
      "Void Stalker": "ผู้ล่าแห่งความว่างเปล่า",
