      "Exit to Whispering Woods": "กลับสู่ผืนป่ากระซิบ",
      "Elderwood Hollow": "โพรงพฤกษาโบราณ",
      "Enter Elderwood Hollow": "เข้าสู่โพรงพฤกษาโบราณ",
